#!/usr/bin/env bash
# Regenerate /etc/nginx/conf.d/cloudflare-origin.conf from Cloudflare's published edge ranges (PAT-269).
#
# The generated file does two things for every server block on the VM:
#   1. real_ip — when the TCP peer is a Cloudflare edge (or loopback, for the cloudflared tunnel),
#      $remote_addr becomes the visitor's address taken from CF-Connecting-IP. The X-Real-IP /
#      X-Forwarded-For that nginx forwards therefore carry the visitor, so the backend's per-IP
#      rate limit (RateLimitFilter / ClientIpResolver) and audit_log.ip_address stop being keyed
#      on Cloudflare's edge IPs (before 2026-10-23 every audit row was 172.69.x / 162.159.x / 104.x).
#   2. $cf_origin — 1 when the ORIGINAL peer ($realip_remote_addr, i.e. before the rewrite above)
#      is Cloudflare or loopback, else 0. twcql.com's server blocks `return 403` when it is 0, so the
#      origin cannot be reached directly by IP any more (that path bypassed Cloudflare's WAF, rate
#      limiting and bot protection). nginx's own allow/deny evaluates the REWRITTEN address, which is
#      why a `geo` map on $realip_remote_addr is used instead of allow/deny.
#
# Installed at /usr/local/sbin/update-cloudflare-ips.sh; /etc/cron.d/update-cloudflare-ips runs it
# weekly. Safe to re-run: writes only when the ranges changed, gates on `nginx -t`, restores the
# previous file if the test fails. `--no-reload` generates and tests without reloading nginx.
set -u
OUT=/etc/nginx/conf.d/cloudflare-origin.conf
MIN_V4=10
MIN_V6=4
tmp=$(mktemp -d) || exit 1
trap 'rm -rf "$tmp"' EXIT

fetch() { curl -fsS -m 20 --retry 2 "https://www.cloudflare.com/$1" -o "$tmp/$1"; }
if ! fetch ips-v4 || ! fetch ips-v6; then
  echo "update-cloudflare-ips: fetch failed; keeping $OUT" >&2
  exit 1
fi
v4=$(grep -c -E '^[0-9]{1,3}(\.[0-9]{1,3}){3}/[0-9]{1,2}$' "$tmp/ips-v4")
v6=$(grep -c -E '^[0-9a-fA-F:]+/[0-9]{1,3}$' "$tmp/ips-v6")
if [ "$v4" -lt "$MIN_V4" ] || [ "$v6" -lt "$MIN_V6" ] \
   || [ "$v4" -ne "$(grep -c . "$tmp/ips-v4")" ] || [ "$v6" -ne "$(grep -c . "$tmp/ips-v6")" ]; then
  echo "update-cloudflare-ips: implausible list (v4=$v4 v6=$v6); keeping $OUT" >&2
  exit 1
fi

{
  echo '# Generated by update-cloudflare-ips.sh - do not edit by hand (source: docker/nginx-vm/ in the CQL repo, PAT-269).'
  echo '# Cloudflare edge ranges from https://www.cloudflare.com/ips-v4 and /ips-v6, plus loopback for the cloudflared tunnel.'
  echo
  echo '# 1. Trust CF-Connecting-IP from these peers: $remote_addr becomes the visitor address.'
  for r in $(cat "$tmp/ips-v4" "$tmp/ips-v6") 127.0.0.1/32 ::1/128; do echo "set_real_ip_from $r;"; done
  echo 'real_ip_header CF-Connecting-IP;'
  echo
  echo '# 2. $cf_origin = was the ORIGINAL TCP peer Cloudflare or loopback? (allow/deny would see the rewritten address.)'
  echo 'geo $realip_remote_addr $cf_origin {'
  echo '    default 0;'
  for r in 127.0.0.1/32 ::1/128 $(cat "$tmp/ips-v4" "$tmp/ips-v6"); do echo "    $r 1;"; done
  echo '}'
} > "$tmp/new.conf"

if [ -f "$OUT" ] && cmp -s "$tmp/new.conf" "$OUT"; then
  echo "update-cloudflare-ips: unchanged ($v4 v4 + $v6 v6 ranges)"
  exit 0
fi
[ -f "$OUT" ] && cp -a "$OUT" "$tmp/prev.conf"
install -m 644 "$tmp/new.conf" "$OUT"
if nginx -t >/dev/null 2>&1; then
  if [ "${1:-}" = "--no-reload" ]; then
    echo "update-cloudflare-ips: wrote $OUT ($v4 v4 + $v6 v6 ranges), nginx not reloaded"
  else
    systemctl reload nginx
    echo "update-cloudflare-ips: wrote $OUT ($v4 v4 + $v6 v6 ranges), nginx reloaded"
  fi
else
  if [ -f "$tmp/prev.conf" ]; then install -m 644 "$tmp/prev.conf" "$OUT"; else rm -f "$OUT"; fi
  echo "update-cloudflare-ips: nginx -t failed with the new ranges; previous file restored" >&2
  nginx -t 2>&1 | tail -2 >&2
  exit 1
fi
